    19	public final class Api {
    20	    private static final ObjectMapper JSON = new ObjectMapper()
    21	            .configure(JsonGenerator.Feature.WRITE_BIGDECIMAL_AS_PLAIN, true)
    22	            .disable(SerializationFeature.FAIL_ON_EMPTY_BEANS);
    23	    private static final Pattern MONTH = Pattern.compile("\\d{4}-\\d{2}");
    24	    private static final Pattern DATE = Pattern.compile("\\d{4}-\\d{2}-\\d{2}");
