    32	    public Javalin start(int port) {
    33	        Javalin app = Javalin.create(cfg -> cfg.showJavalinBanner = false);
    34	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.status, e.code, e.getMessage()));
    35	        app.exception(Exception.class, (e, ctx) -> {
    36	            e.printStackTrace();
    37	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
    38	        });
    39	
    40	        app.get("/rooms", ctx -> json(ctx, 200, Room.ALL.stream().map(Api::roomView).toList()));
    41	        app.post("/reservations", ctx -> json(ctx, 201, reservationView(service.create(parseNew(ctx)))));
    42	        app.get("/reservations/{id}", ctx -> json(ctx, 200, reservationView(service.get(id(ctx)))));
    43	        app.post("/reservations/{id}/confirmation", ctx -> json(ctx, 200, reservationView(service.confirm(id(ctx)))));
    44	        app.post("/reservations/{id}/cancellation", ctx -> json(ctx, 200, reservationView(service.cancel(id(ctx)))));
    45	        app.post("/reservations/{id}/check-in", ctx -> json(ctx, 200, reservationView(service.checkIn(id(ctx)))));
    46	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, documentView(service.checkOut(id(ctx)))));
    47	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, documentView(service.document(id(ctx)))));
    48	        app.get("/messages", ctx -> json(ctx, 200, service.messages().stream().map(Api::messageView).toList()));
    49	        app.get("/reports/occupancy", ctx -> {
    50	            LocalDate date = parseDate(ctx.queryParam("date"), "date");
    51	            csv(ctx, Reports.occupancy(service.occupying(date)));
    52	        });
    53	        app.get("/reports/revenue", ctx -> {
    54	            String raw = ctx.queryParam("month");
    55	            if (raw == null || !MONTH.matcher(raw).matches()) throw ApiException.invalid("month deve ser AAAA-MM");
    56	            YearMonth month;
    57	            try {
    58	                month = YearMonth.parse(raw);
    59	            } catch (DateTimeParseException e) {
    60	                throw ApiException.invalid("month deve ser AAAA-MM");
    61	            }
    62	            csv(ctx, Reports.revenue(service.startingBetween(month.atDay(1), month.plusMonths(1).atDay(1))));
    63	        });
    64	        return app.start(port);
    65	    }
