    69	    private static ReservationService.NewReservation parseNew(Context ctx) {
    70	        JsonNode body;
    71	        try {
    72	            body = JSON.readTree(ctx.body());
    73	        } catch (JsonProcessingException e) {
    74	            throw ApiException.invalid("Corpo não é um JSON válido");
    75	        }
    76	        if (body == null || !body.isObject()) throw ApiException.invalid("Corpo deve ser um objeto JSON");
    77	
    78	        String guestName = text(body, "guestName");
    79	        String guestEmail = text(body, "guestEmail");
    80	        int roomNumber = integer(body, "roomNumber");
    81	        int guests = integer(body, "guests");
    82	        LocalDate checkIn = parseDate(optionalText(body, "checkIn"), "checkIn");
    83	        LocalDate checkOut = parseDate(optionalText(body, "checkOut"), "checkOut");
    84	        RatePlan plan;
    85	        try {
    86	            plan = RatePlan.valueOf(text(body, "ratePlan"));
    87	        } catch (IllegalArgumentException e) {
    88	            throw ApiException.invalid("ratePlan inválido");
    89	        }
    90	        GuestIdentity identity = identity(body);
    91	        if (!checkOut.isAfter(checkIn)) throw ApiException.invalid("checkOut deve ser depois de checkIn");
    92	        if (guests < 1) throw ApiException.invalid("guests deve ser pelo menos 1");
    93	        return new ReservationService.NewReservation(roomNumber, guestName, guestEmail, identity, checkIn, checkOut,
    94	                guests, plan);
    95	    }
    96	
    97	    /** Exactly one of: guestCpf | companyCnpj+companyName | guestPassport+guestCountry. */
    98	    private static GuestIdentity identity(JsonNode body) {
    99	        String cpf = optionalText(body, "guestCpf");
   100	        String cnpj = optionalText(body, "companyCnpj");
   101	        String company = optionalText(body, "companyName");
   102	        String passport = optionalText(body, "guestPassport");
   103	        String country = optionalText(body, "guestCountry");
   104	        boolean individual = cpf != null;
   105	        boolean corporate = cnpj != null || company != null;
   106	        boolean foreign = passport != null || country != null;
   107	        if (java.util.stream.Stream.of(individual, corporate, foreign).filter(b -> b).count() != 1) {
   108	            throw ApiException.invalid("Informe guestCpf, ou companyCnpj e companyName, ou guestPassport e guestCountry");
   109	        }
   110	        if (individual) return new GuestIdentity.Individual(cpf);
   111	        if (corporate) {
   112	            if (cnpj == null || company == null) throw ApiException.invalid("companyCnpj e companyName vão juntos");
   113	            return new GuestIdentity.Company(cnpj, company);
   114	        }
   115	        if (passport == null || country == null) throw ApiException.invalid("guestPassport e guestCountry vão juntos");
   116	        return new GuestIdentity.Foreigner(passport, country);
   117	    }
   118	
   119	    /** Absent, null or blank counts as missing (null); a non-string value is invalid. */
   120	    private static String optionalText(JsonNode body, String field) {
   121	        JsonNode node = body.get(field);
   122	        if (node == null || node.isNull()) return null;
   123	        if (!node.isTextual()) throw ApiException.invalid(field + " deve ser texto");
   124	        return node.asText().isBlank() ? null : node.asText().strip();
   125	    }
   126	
   127	    private static String text(JsonNode body, String field) {
   128	        String value = optionalText(body, field);
   129	        if (value == null) throw ApiException.invalid(field + " é obrigatório");
   130	        return value;
   131	    }
   132	
   133	    private static int integer(JsonNode body, String field) {
   134	        JsonNode node = body.get(field);
   135	        if (node == null || node.isNull()) throw ApiException.invalid(field + " é obrigatório");
   136	        if (!node.isIntegralNumber() || !node.canConvertToInt()) throw ApiException.invalid(field + " deve ser inteiro");
   137	        return node.intValue();
   138	    }
   139	
   140	    private static LocalDate parseDate(String raw, String field) {
   141	        if (raw == null || !DATE.matcher(raw).matches()) throw ApiException.invalid(field + " deve ser AAAA-MM-DD");
   142	        try {
   143	            return LocalDate.parse(raw);
   144	        } catch (DateTimeParseException e) {
   145	            throw ApiException.invalid(field + " deve ser AAAA-MM-DD");
   146	        }
   147	    }
   148	
   149	    private static long id(Context ctx) {
   150	        try {
   151	            return Long.parseLong(ctx.pathParam("id"));
   152	        } catch (NumberFormatException e) {
   153	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva não encontrada");
   154	        }
   155	    }
   156	
   157	    // ---- responses ----
   158	
   159	    private static void json(Context ctx, int status, Object body) {
   160	        try {
   161	            ctx.status(status).contentType("application/json").result(JSON.writeValueAsString(body));
   162	        } catch (JsonProcessingException e) {
   163	            throw new IllegalStateException(e);
   164	        }
   165	    }
   166	
   167	    private static void csv(Context ctx, String body) {
   168	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));
   169	    }
   170	
   171	    private static void error(Context ctx, int status, String code, String message) {
   172	        json(ctx, status, Map.of("error", code, "message", message));
   173	    }
   174	
