     3	import java.sql.Connection;
     4	import java.sql.Date;
     5	import java.sql.PreparedStatement;
     6	import java.sql.ResultSet;
     7	import java.sql.SQLException;
     8	import java.sql.Statement;
     9	import java.time.LocalDate;
    10	import java.util.ArrayList;
    11	import java.util.List;
    12	import java.util.Optional;
    13	
    14	/** SQL access for reservations and messages. Callers provide the transaction. */
    15	public final class Store {
    16	    private Store() {}
    17	
    18	    private static final String COLUMNS = """
    19	            id, room_number, guest_name, guest_email, guest_cpf, company_cnpj, company_name,
    20	            guest_passport, guest_country, check_in, check_out, guests, rate_plan, nights,
    21	            subtotal, discount, total, status, amount_paid, refund""";
    22	
    23	    /** Serializes bookings of one room within the transaction. */
    24	    public static void lockRoom(Connection c, int roomNumber) throws SQLException {
    25	        try (PreparedStatement ps = c.prepareStatement("SELECT pg_advisory_xact_lock(?)")) {
    26	            ps.setLong(1, roomNumber);
    27	            ps.execute();
    28	        }
    29	    }
    30	
    31	    public static boolean isRoomBusy(Connection c, int roomNumber, LocalDate checkIn, LocalDate checkOut)
    32	            throws SQLException {
    33	        try (PreparedStatement ps = c.prepareStatement("""
    34	                SELECT 1 FROM reservations
    35	                WHERE room_number = ? AND status <> 'CANCELLED' AND check_in < ? AND check_out > ?
    36	                LIMIT 1""")) {
    37	            ps.setInt(1, roomNumber);
    38	            ps.setDate(2, Date.valueOf(checkOut));
    39	            ps.setDate(3, Date.valueOf(checkIn));
    40	            try (ResultSet rs = ps.executeQuery()) {
    41	                return rs.next();
    42	            }
    43	        }
    44	    }
    45	
    46	    public static Reservation insert(Connection c, Reservation r) throws SQLException {
    47	        try (PreparedStatement ps = c.prepareStatement("""
    48	                INSERT INTO reservations (room_number, guest_name, guest_email, guest_cpf, company_cnpj,
    49	                    company_name, guest_passport, guest_country, check_in, check_out, guests, rate_plan,
    50	                    nights, subtotal, discount, total, status, amount_paid, refund)
    51	                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""", Statement.RETURN_GENERATED_KEYS)) {
    52	            int i = 1;
    53	            ps.setInt(i++, r.roomNumber());
    54	            ps.setString(i++, r.guestName());
    55	            ps.setString(i++, r.guestEmail());
    56	            ps.setString(i++, r.identity().cpf());
    57	            ps.setString(i++, r.identity().cnpj());
    58	            ps.setString(i++, r.identity().companyName());
    59	            ps.setString(i++, r.identity().passport());
    60	            ps.setString(i++, r.identity().country());
    61	            ps.setDate(i++, Date.valueOf(r.checkIn()));
    62	            ps.setDate(i++, Date.valueOf(r.checkOut()));
    63	            ps.setInt(i++, r.guests());
    64	            ps.setString(i++, r.ratePlan().name());
    65	            ps.setInt(i++, r.nights());
    66	            ps.setBigDecimal(i++, r.subtotal());
    67	            ps.setBigDecimal(i++, r.discount());
    68	            ps.setBigDecimal(i++, r.total());
    69	            ps.setString(i++, r.status().name());
    70	            ps.setBigDecimal(i++, r.amountPaid());
    71	            ps.setBigDecimal(i, r.refund());
    72	            ps.executeUpdate();
    73	            try (ResultSet keys = ps.getGeneratedKeys()) {
    74	                keys.next();
    75	                return find(c, keys.getLong(1), false).orElseThrow();
    76	            }
    77	        }
    78	    }
    79	
    80	    public static Optional<Reservation> find(Connection c, long id, boolean forUpdate) throws SQLException {
    81	        try (PreparedStatement ps = c.prepareStatement(
    82	                "SELECT " + COLUMNS + " FROM reservations WHERE id = ?" + (forUpdate ? " FOR UPDATE" : ""))) {
    83	            ps.setLong(1, id);
    84	            try (ResultSet rs = ps.executeQuery()) {
    85	                return rs.next() ? Optional.of(read(rs)) : Optional.empty();
    86	            }
    87	        }
    88	    }
    89	
    90	    public static void updateState(Connection c, Reservation r) throws SQLException {
    91	        try (PreparedStatement ps = c.prepareStatement(
    92	                "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
    93	            ps.setString(1, r.status().name());
    94	            ps.setBigDecimal(2, r.amountPaid());
    95	            ps.setBigDecimal(3, r.refund());
    96	            ps.setLong(4, r.id());
    97	            ps.executeUpdate();
    98	        }
    99	    }
   100	
   101	    /** Paid reservations occupying a room on the given night. */
   102	    public static List<Reservation> occupying(Connection c, LocalDate night) throws SQLException {
   103	        return query(c, "WHERE status IN ('CONFIRMED','CHECKED_IN','CHECKED_OUT') AND check_in <= ? AND check_out > ? "
   104	                + "ORDER BY room_number, id", night, night);
   105	    }
   106	
   107	    /** Reservations starting within [from, to) that kept money with the inn. */
   108	    public static List<Reservation> startingBetween(Connection c, LocalDate from, LocalDate to) throws SQLException {
   109	        return query(c, "WHERE check_in >= ? AND check_in < ? AND amount_paid - COALESCE(refund, 0) > 0 "
   110	                + "ORDER BY check_in, id", from, to);
   111	    }
   112	
   113	    private static List<Reservation> query(Connection c, String tail, LocalDate a, LocalDate b) throws SQLException {
   114	        try (PreparedStatement ps = c.prepareStatement("SELECT " + COLUMNS + " FROM reservations " + tail)) {
   115	            ps.setDate(1, Date.valueOf(a));
   116	            ps.setDate(2, Date.valueOf(b));
   117	            List<Reservation> out = new ArrayList<>();
   118	            try (ResultSet rs = ps.executeQuery()) {
   119	                while (rs.next()) out.add(read(rs));
   120	            }
   121	            return out;
   122	        }
   123	    }
   124	
   125	    public static void insertMessage(Connection c, String channel, String to, String subject, String body)
   126	            throws SQLException {
   127	        try (PreparedStatement ps = c.prepareStatement(
   128	                "INSERT INTO messages (channel, recipient, subject, body) VALUES (?,?,?,?)")) {
   129	            ps.setString(1, channel);
   130	            ps.setString(2, to);
   131	            ps.setString(3, subject);
   132	            ps.setString(4, body);
   133	            ps.executeUpdate();
   134	        }
   135	    }
   136	
   137	    public static List<Message> messages(Connection c) throws SQLException {
   138	        try (Statement s = c.createStatement();
   139	             ResultSet rs = s.executeQuery("SELECT id, channel, recipient, subject, body FROM messages ORDER BY id")) {
   140	            List<Message> out = new ArrayList<>();
   141	            while (rs.next()) {
   142	                out.add(new Message(rs.getLong(1), rs.getString(2), rs.getString(3), rs.getString(4), rs.getString(5)));
   143	            }
   144	            return out;
   145	        }
   146	    }
   147	
   148	    private static Reservation read(ResultSet rs) throws SQLException {
   149	        GuestIdentity identity;
   150	        if (rs.getString("guest_cpf") != null) {
   151	            identity = new GuestIdentity.Individual(rs.getString("guest_cpf"));
   152	        } else if (rs.getString("company_cnpj") != null) {
   153	            identity = new GuestIdentity.Company(rs.getString("company_cnpj"), rs.getString("company_name"));
   154	        } else {
   155	            identity = new GuestIdentity.Foreigner(rs.getString("guest_passport"), rs.getString("guest_country"));
   156	        }
   157	        return new Reservation(
   158	                rs.getLong("id"),
   159	                rs.getInt("room_number"),
   160	                rs.getString("guest_name"),
   161	                rs.getString("guest_email"),
   162	                identity,
   163	                rs.getDate("check_in").toLocalDate(),
   164	                rs.getDate("check_out").toLocalDate(),
   165	                rs.getInt("guests"),
   166	                RatePlan.valueOf(rs.getString("rate_plan")),
   167	                rs.getInt("nights"),
   168	                rs.getBigDecimal("subtotal"),
   169	                rs.getBigDecimal("discount"),
   170	                rs.getBigDecimal("total"),
   171	                ReservationStatus.valueOf(rs.getString("status")),
   172	                rs.getBigDecimal("amount_paid"),
   173	                rs.getBigDecimal("refund"));
   174	    }
   175	}
