     1	package pousada;
     2	
     3	import java.time.LocalDate;
     4	import java.util.List;
     5	
     6	public final class ReservationService {
     7	    private final Database db;
     8	
     9	    public ReservationService(Database db) {
    10	        this.db = db;
    11	    }
    12	
    13	    public record NewReservation(int roomNumber, String guestName, String guestEmail, GuestIdentity identity,
    14	                                 LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {}
    15	
    16	    public Reservation create(NewReservation n) {
    17	        Room room = Room.find(n.roomNumber())
    18	                .orElseThrow(() -> new ApiException(404, "ROOM_NOT_FOUND", "Quarto não encontrado: " + n.roomNumber()));
    19	        if (n.guests() > room.type().capacity) {
    20	            throw new ApiException(422, "CAPACITY_EXCEEDED",
    21	                    "O quarto " + room.number() + " comporta até " + room.type().capacity + " pessoas");
    22	        }
    23	        Quote quote = Quote.of(room.type(), n.checkIn(), n.checkOut(), n.ratePlan());
    24	        return db.inTransaction(c -> {
    25	            Store.lockRoom(c, room.number());
    26	            if (Store.isRoomBusy(c, room.number(), n.checkIn(), n.checkOut())) {
    27	                throw new ApiException(409, "ROOM_UNAVAILABLE", "Quarto já reservado em alguma das noites");
    28	            }
    29	            return Store.insert(c, new Reservation(0, room.number(), n.guestName(), n.guestEmail(), n.identity(),
    30	                    n.checkIn(), n.checkOut(), n.guests(), n.ratePlan(), quote.nights(), quote.subtotal(),
    31	                    quote.discount(), quote.total(), ReservationStatus.PENDING, Money.ZERO, null));
    32	        });
    33	    }
    34	
    35	    public Reservation get(long id) {
    36	        return db.inTransaction(c -> Store.find(c, id, false).orElseThrow(() -> notFound(id)));
    37	    }
    38	
    39	    public Reservation confirm(long id) {
    40	        return db.inTransaction(c -> {
    41	            Reservation r = require(c, id, ReservationStatus.PENDING, "Só é possível confirmar uma reserva pendente");
    42	            Reservation paid = with(r, ReservationStatus.CONFIRMED, r.total(), r.refund());
    43	            Store.updateState(c, paid);
    44	            Store.insertMessage(c, "EMAIL", paid.guestEmail(), Documents.confirmationSubject(),
    45	                    Documents.confirmationBody(paid, Documents.issue(paid)));
    46	            return paid;
    47	        });
    48	    }
    49	
    50	    public Reservation cancel(long id) {
    51	        return db.inTransaction(c -> {
    52	            Reservation r = Store.find(c, id, true).orElseThrow(() -> notFound(id));
    53	            if (r.status() != ReservationStatus.PENDING && r.status() != ReservationStatus.CONFIRMED) {
    54	                throw ApiException.notAllowed("Só é possível cancelar uma reserva pendente ou confirmada");
    55	            }
    56	            // A pending reservation has paid nothing, so its refund is zero either way.
    57	            var refund = r.ratePlan().refundable ? r.amountPaid() : Money.ZERO;
    58	            Reservation cancelled = with(r, ReservationStatus.CANCELLED, r.amountPaid(), refund);
    59	            Store.updateState(c, cancelled);
    60	            return cancelled;
    61	        });
    62	    }
    63	
    64	    public Reservation checkIn(long id) {
    65	        return db.inTransaction(c -> {
