    21	                    "O quarto " + room.number() + " comporta até " + room.type().capacity + " pessoas");
    22	        }
    23	        Quote quote = Quote.of(room.type(), n.checkIn(), n.checkOut(), n.ratePlan());
    24	        return db.inTransaction(c -> {
    25	            Store.lockRoom(c, room.number());
    26	            if (Store.isRoomBusy(c, room.number(), n.checkIn(), n.checkOut())) {
    27	                throw new ApiException(409, "ROOM_UNAVAILABLE", "Quarto já reservado em alguma das noites");
    28	            }
    29	            return Store.insert(c, new Reservation(0, room.number(), n.guestName(), n.guestEmail(), n.identity(),
    30	                    n.checkIn(), n.checkOut(), n.guests(), n.ratePlan(), quote.nights(), quote.subtotal(),
