    10	/** Connection pool, schema creation and transaction helper. */
    11	public final class Database implements AutoCloseable {
    12	    private final HikariDataSource dataSource;
    13	
    14	    public Database(String url, String user, String password) {
    15	        HikariConfig config = new HikariConfig();
    16	        config.setJdbcUrl(url);
    17	        config.setUsername(user);
    18	        config.setPassword(password);
    19	        config.setMaximumPoolSize(10);
    20	        config.setInitializationFailTimeout(60_000); // the database may still be starting
    21	        this.dataSource = new HikariDataSource(config);
    22	        createSchema();
    23	    }
    24	
    25	    public interface TxWork<T> {
    26	        T run(Connection c) throws SQLException;
    27	    }
    28	
    29	    public <T> T inTransaction(TxWork<T> work) {
    30	        try (Connection c = dataSource.getConnection()) {
    31	            c.setAutoCommit(false);
    32	            try {
    33	                T result = work.run(c);
    34	                c.commit();
    35	                return result;
    36	            } catch (Throwable t) {
    37	                c.rollback();
    38	                throw t;
    39	            }
    40	        } catch (SQLException e) {
    41	            throw new IllegalStateException("Database error: " + e.getMessage(), e);
    42	        }
    43	    }
    44	
    45	    private void createSchema() {
    46	        inTransaction(c -> {
    47	            try (Statement s = c.createStatement()) {
    48	                s.execute("SELECT pg_advisory_xact_lock(7070001)"); // several instances may start together
    49	                s.execute("""
    50	                        CREATE TABLE IF NOT EXISTS reservations (
    51	                            id BIGSERIAL PRIMARY KEY,
    52	                            room_number INT NOT NULL,
    53	                            guest_name TEXT NOT NULL,
    54	                            guest_email TEXT NOT NULL,
    55	                            guest_cpf TEXT,
    56	                            company_cnpj TEXT,
    57	                            company_name TEXT,
    58	                            guest_passport TEXT,
    59	                            guest_country TEXT,
    60	                            check_in DATE NOT NULL,
    61	                            check_out DATE NOT NULL,
    62	                            guests INT NOT NULL,
    63	                            rate_plan TEXT NOT NULL,
    64	                            nights INT NOT NULL,
    65	                            subtotal NUMERIC(12,2) NOT NULL,
    66	                            discount NUMERIC(12,2) NOT NULL,
    67	                            total NUMERIC(12,2) NOT NULL,
    68	                            status TEXT NOT NULL,
    69	                            amount_paid NUMERIC(12,2) NOT NULL,
    70	                            refund NUMERIC(12,2)
    71	                        )""");
    72	                s.execute("CREATE INDEX IF NOT EXISTS reservations_room_idx ON reservations (room_number, check_in)");
    73	                s.execute("""
    74	                        CREATE TABLE IF NOT EXISTS messages (
    75	                            id BIGSERIAL PRIMARY KEY,
    76	                            channel TEXT NOT NULL,
    77	                            recipient TEXT NOT NULL,
    78	                            subject TEXT NOT NULL,
    79	                            body TEXT NOT NULL
    80	                        )""");
    81	            }
    82	            return null;
    83	        });
    84	    }
    85	
    86	    @Override
    87	    public void close() {
    88	        dataSource.close();
    89	    }
    90	}
