    33	    private static String format(BigDecimal value, char grouping, char decimal) {
    34	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(Locale.ROOT);
    35	        symbols.setGroupingSeparator(grouping);
    36	        symbols.setDecimalSeparator(decimal);
    37	        DecimalFormat format = new DecimalFormat("#,##0.00", symbols);
    38	        format.setRoundingMode(RoundingMode.HALF_EVEN);
    39	        return format.format(round(value));
