     7	public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
     8	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
     9	
    10	    public static Quote of(RoomType type, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    11	        BigDecimal subtotal = Money.ZERO;
    12	        int nights = 0;
    13	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    14	            subtotal = subtotal.add(nightPrice(type, night));
    15	            nights++;
    16	        }
    17	        BigDecimal discount = Money.round(subtotal.multiply(plan.discountRate));
    18	        return new Quote(nights, subtotal, discount, subtotal.subtract(discount));
    19	    }
    20	
    21	    static BigDecimal nightPrice(RoomType type, LocalDate night) {
    22	        BigDecimal rate = type.nightlyRate;
    23	        return isHighSeason(night) ? Money.round(rate.multiply(HIGH_SEASON_FACTOR)) : rate;
    24	    }
    25	
    26	    /** Dec 15 through end of Feb, and all of July. */
    27	    static boolean isHighSeason(LocalDate night) {
    28	        int month = night.getMonthValue();
    29	        return month == 1 || month == 2 || month == 7
    30	                || (month == 12 && night.getDayOfMonth() >= 15);
    31	    }
